function d_inverse(P,R){var A=P.A||[[3,1],[1,2]],y=P.y||[9,8];var det=A[0][0]*A[1][1]-A[0][1]*A[1][0];var x=[(A[1][1]*y[0]-A[0][1]*y[1])/det,(-A[1][0]*y[0]+A[0][0]*y[1])/det];var res=[A[0][0]*x[0]+A[0][1]*x[1]-y[0],A[1][0]*x[0]+A[1][1]*x[1]-y[1]];return{solution:x.map(function(v){return +v.toFixed(6);}),residual_norm:+Math.hypot(res[0],res[1]).toFixed(9)};}

